def schema_contract_ref(schema_name: str) -> str:
    return SCHEMA_REGISTRY[schema_name]


def schema_contract_refs() -> tuple[str, ...]:
    return tuple(SCHEMA_REGISTRY.values())


def split_schema_contract_ref(ref: str) -> tuple[str, str | None]:
    relative_path, separator, fragment = ref.partition("#")
    if not separator:
        return relative_path, None
    prefix = "/$defs/"
    if not fragment.startswith(prefix):
        raise ValueError(f"unsupported schema ref fragment: {ref}")
    return relative_path, fragment.removeprefix(prefix)
